const {chromium}=require('/Users/ph.qian/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');const fs=require('node:fs/promises'),assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});try{const p=await browser.newPage();await p.goto(process.env.VDOC_TEST_URL||'http://127.0.0.1:4178/');await p.getByRole('button',{name:'New document',exact:true}).click();const body=p.getByRole('textbox',{name:'Document body',exact:true});await body.fill('First');await p.keyboard.press('Enter');await p.keyboard.type('Second');await p.keyboard.press('Meta+a');await p.getByRole('button',{name:'Bulleted list',exact:true}).click();await body.focus();await p.keyboard.press('ArrowRight');await p.keyboard.press('Meta+ArrowDown');await p.getByRole('button',{name:'Format',exact:true}).click();await p.getByRole('menuitem',{name:'Increase indent',exact:true}).click();await p.waitForTimeout(400);const focus=await p.evaluate(()=>({active:document.activeElement?.outerHTML.slice(0,500),selection:window.vdoc.snapshot().selection,document:window.vdoc.snapshot().document}));await p.keyboard.type('Z');await p.keyboard.press('Enter');const after=await p.evaluate(()=>window.vdoc.snapshot().document);assert(focus.active.startsWith('<div contenteditable="true"'));assert(JSON.stringify(after).includes('Z'));await p.getByRole('button',{name:'Edit',exact:true}).click();await p.getByRole('menuitem',{name:/^Find and replace/}).click();await p.waitForTimeout(400);assert(await p.getByLabel('Find text',{exact:true}).evaluate(el=>el===document.activeElement));await p.getByRole('button',{name:'Close find and replace',exact:true}).click();await p.getByRole('button',{name:'Insert',exact:true}).click();await p.getByRole('menuitem',{name:'Image from device',exact:true}).click();await p.waitForTimeout(400);assert(await p.getByRole('dialog').evaluate(el=>el.contains(document.activeElement)));await p.keyboard.press('Escape');await fs.writeFile('tests/fixtures/combined-workflow-20261010/menu-focus-fixed.json',JSON.stringify({focus,after},null,2));console.log('Menu returns real typing and Enter to editor; search and image dialog retain their focus.');}finally{await browser.close();}})();
